export type SITEMAP_QUERY_RESULT = Array<
  | {
      _type: 'blog.post'
      _updatedAt: string
      language: string | null
      metadata: {
        slug: Slug | null
      } | null
      isFallback: boolean
      translations:
        | Array<{
            lang: string
            slug: string | null
          }>
        | Array<{
            lang: string | 'en'
            slug: string | null
          }>
    }
  | {
      _type: 'page'
      _updatedAt: string
      language: string | null
      metadata: {
        slug: Slug | null
      } | null
      isFallback: boolean
      translations:
        | Array<{
            lang: string
            slug: string | null
          }>
        | Array<{
            lang: string | 'en'
            slug: string | null
          }>
    }
>

