export type SEARCH_QUERY_RESULT = Array<
  | {
      _id: string
      _type: 'blog.post'
      title: string | null
      metadata: Metadata | null
    }
  | {
      _id: string
      _type: 'page'
      title: string | null
      metadata: Metadata | null
    }
>

